auto deadline = std::chrono::steady_clock::now() + budget;
std::vector<std::future<Offer>> futs;
for (auto& r : recipients) futs.push_back(std::async(std::launch::async, ask, r));
std::vector<Offer> got;
for (auto& f : futs)
    if (f.wait_for(deadline - std::chrono::steady_clock::now()) == std::future_status::ready)
        got.push_back(f.get());     // each get() may throw: collect per-future

